import itertools
import random

def has_cycle_of_length(edges, n, length):
    """Check if graph has a cycle of given length."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS/DFS to find cycles
    def dfs(start, current, parent, depth, visited):
        if depth == length:
            return current == start
        for neighbor in adj[current]:
            if neighbor == parent:
                continue
            if depth < length - 1 and neighbor in visited:
                continue
            if neighbor == start and depth == length - 1:
                return True
            if neighbor not in visited:
                visited.add(neighbor)
                if dfs(start, neighbor, current, depth + 1, visited):
                    return True
                visited.remove(neighbor)
        return False

    for start in range(n):
        visited = {start}
        if dfs(start, start, -1, 0, visited):
            return True
    return False

def check_girth(edges, n, min_girth):
    """Check if graph has girth at least min_girth."""
    for length in range(3, min_girth):
        if has_cycle_of_length(edges, n, length):
            return False
    return True

def is_k_colorable(edges, n, k):
    """Check if graph is k-colorable using backtracking."""
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n

    def backtrack(vertex):
        if vertex == n:
            return True
        for color in range(k):
            valid = True
            for neighbor in adj[vertex]:
                if colors[neighbor] == color:
                    valid = False
                    break
            if valid:
                colors[vertex] = color
                if backtrack(vertex + 1):
                    return True
                colors[vertex] = -1
        return False

    return backtrack(0)

