def verify_solution(edges, n=23):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check all edges are valid
    for u, v in edges:
        assert 0 <= u < v < n, f"Invalid edge: ({u}, {v})"

    # Check for cycles of length 3, 4, 5
    def find_cycles_of_length(length):
        cycles = []
        # Use DFS
        def dfs(start, current, parent, depth, path):
            if depth == length:
                if current == start:
                    cycles.append(path[:])
                return
            for neighbor in adj[current]:
                if neighbor == parent:
                    continue
                if depth < length - 1 and neighbor in path:
                    continue
                if neighbor == start and depth == length - 1:
                    cycles.append(path + [neighbor])
                    return
                if neighbor not in path:
                    path.append(neighbor)
                    dfs(start, neighbor, current, depth + 1, path)
                    path.pop()

        for start in range(n):
            dfs(start, start, -1, 0, [start])
        return cycles

    for length in [3, 4, 5]:
        cycles = find_cycles_of_length(length)
        if cycles:
            print(f"Found {len(cycles)} cycles of length {length}")
            for c in cycles[:3]:
                print(f"  {c}")
            return False
        else:
            print(f"No cycles of length {length}")

    # Check 4-colorability
    colors = [-1] * n
    def is_k_colorable(k):
        def backtrack(vertex):
            if vertex == n:
                return True
            for color in range(k):
                valid = True
                for neighbor in adj[vertex]:
                    if colors[neighbor] == color:
                        valid = False
                        break
                if valid:
                    colors[vertex] = color
                    if backtrack(vertex + 1):
                        return True
                    colors[vertex] = -1
            return False
        return backtrack(0)

    if is_k_colorable(4):
        print("Graph is 4-colorable")
        print(f"Colors: {colors}")
    else:
        print("Graph is NOT 4-colorable")
        return False

    print(f"Number of edges: {len(edges)}")
    return True

